// -----------------------------------------------------------------------------
// Text helpers
// -----------------------------------------------------------------------------

function norm(value: string): string {
  return value
    .normalize("NFD")
    .replace(/\p{Diacritic}/gu, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function slugify(value: string): string {
  return value
    .normalize("NFD")
    .replace(/\p{Diacritic}/gu, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .replace(/_+/g, "_");
}

function hashKey(value: string): string {
  return createHash("sha256").update(value).digest("hex").slice(0, 12);
}

function truncate(value: string, max: number): string {
  if (value.length <= max) return value;
  const cut = value.slice(0, max);
  const space = cut.lastIndexOf(" ");
  return `${space > max * 0.6 ? cut.slice(0, space) : cut}…`;
}

function stripMarkdown(value: string): string {
  return value
    .replace(/\*\*/g, "")
    .replace(/`/g, "")
    .replace(/^\s*[-*]\s+/, "")
    .replace(/^\s*\[[ x]\]\s*/i, "")
    .replace(/\s+/g, " ")
    .trim();
}

// -----------------------------------------------------------------------------
// Markdown structure
// -----------------------------------------------------------------------------

type Heading = { level: number; title: string; line: number; end: number };

function parseHeadings(lines: string[]): Heading[] {
  const headings: Heading[] = [];

  for (let index = 0; index < lines.length; index += 1) {
    const match = /^(#{1,6})\s+(.*?)\s*$/.exec(lines[index] ?? "");
    if (match && match[1] && match[2]) {
      headings.push({ level: match[1].length, title: match[2], line: index, end: lines.length });
    }
  }

  for (let index = 0; index < headings.length; index += 1) {
    const heading = headings[index];
    if (!heading) continue;
    let end = lines.length;
    for (let next = index + 1; next < headings.length; next += 1) {
      const candidate = headings[next];
      if (candidate && candidate.level <= heading.level) {
        end = candidate.line;
        break;
      }
    }
    heading.end = end;
  }

  return headings;
}

function sectionLines(lines: string[], heading: Heading): string[] {
  return lines.slice(heading.line + 1, heading.end);
}

function isStepContainer(title: string): boolean {
  return /^etapes?$/.test(norm(title));
}

function cleanStepTitle(value: string): string {
  return value
    .replace(/^(Étape|Etape)\s*\d+\s*[—\-–:.]\s*/i, "")
    .replace(/^\d+\s*[.)\-–:]\s*/, "")
    .replace(/\*\*/g, "")
    .replace(/[.:]+$/, "")
    .trim();
}

function bodyToDescription(body: string[], max = 900): string {
  const parts: string[] = [];
  for (const raw of body) {
    const line = stripMarkdown(raw);
    if (!line) continue;
    if (!parts.includes(line)) parts.push(line);
  }
  return truncate(parts.join(" · "), max);
}

type ParsedStep = { titleFr: string; description: string };

function parseNumberedItems(lines: string[]): Array<{ title: string; body: string[] }> {
  const items: Array<{ title: string; body: string[] }> = [];
  let current: { title: string; body: string[] } | null = null;

  for (const raw of lines) {
    const match = /^\s{0,3}(\d+)\.\s+(.*)$/.exec(raw);
    if (match && match[2]) {
      if (current) items.push(current);
      current = { title: match[2].trim(), body: [] };
    } else if (current) {
      current.body.push(raw);
    }
  }

  if (current) items.push(current);
  return items;
}

function parseSteps(lines: string[], headings: Heading[]): ParsedStep[] {
  const containers = headings.filter((heading) => isStepContainer(heading.title));
  const multiple = containers.length > 1;
  const steps: ParsedStep[] = [];

  for (const container of containers) {
    let context = "";
    if (multiple) {
      const parent = [...headings]
        .reverse()
        .find(
          (heading) =>
            heading.line < container.line &&
            heading.level < container.level &&
            !isStepContainer(heading.title),
        );
      context = parent ? cleanStepTitle(parent.title.replace(/^[A-Z]\.\s*/, "")) : "";
    }

    const content = sectionLines(lines, container);
    const subHeadings = headings.filter(
      (heading) =>
        heading.line > container.line &&
        heading.line < container.end &&
        heading.level > container.level,
    );

    if (subHeadings.length > 0) {
      const minLevel = Math.min(...subHeadings.map((heading) => heading.level));
      for (const heading of subHeadings.filter((entry) => entry.level === minLevel)) {
        const title = cleanStepTitle(heading.title);
        const description = bodyToDescription(sectionLines(lines, heading));
        steps.push({
          titleFr: context ? `${context} — ${title}` : title,
          description,
        });
      }
    } else {
      for (const item of parseNumberedItems(content)) {
        const title = cleanStepTitle(item.title);
        steps.push({
          titleFr: context ? `${context} — ${title}` : title,
          description: bodyToDescription(item.body),
        });
      }
    }
  }

  if (steps.length === 0) {
    const etapeHeadings = headings.filter((heading) => /^etape\s*\d+\b/.test(norm(heading.title)));
    if (etapeHeadings.length > 0) {
      for (const heading of etapeHeadings) {
        steps.push({
          titleFr: cleanStepTitle(heading.title),
          description: bodyToDescription(sectionLines(lines, heading)),
        });
      }
    }
  }

  if (steps.length === 0) {
    const excluded =
      /checklist|controle|control|source|delai|piece|objectif|point important|attention|important|resultat|a verifier/i;
    for (const heading of headings) {
      if (isStepContainer(heading.title) || excluded.test(norm(heading.title))) continue;
      const items = parseNumberedItems(sectionLines(lines, heading));
      if (items.length < 2) continue;
      for (const item of items) {
        const title = cleanStepTitle(item.title);
        steps.push({ titleFr: title, description: bodyToDescription(item.body) });
      }
      break;
    }
  }

  return steps;
}

function parseObjective(lines: string[], headings: Heading[]): string {
  const inlineIndex = lines.findIndex((line) => /^\*\*Objectif\s*:\*\*/i.test(line));

  if (inlineIndex >= 0) {
    const collected: string[] = [];
    const first = (lines[inlineIndex] ?? "").replace(/^\*\*Objectif\s*:\*\*\s*/i, "").trim();
    if (first) collected.push(first);
    for (let index = inlineIndex + 1; index < lines.length; index += 1) {
      const line = lines[index] ?? "";
      if (/^#{1,6}\s/.test(line)) break;
      if (!line.trim()) continue;
      collected.push(stripMarkdown(line));
      break;
    }
    return collected.join(" ").trim();
  }

  const heading = headings.find((entry) => norm(entry.title) === "objectif");
  if (!heading) return "";
  return bodyToDescription(sectionLines(lines, heading), 1200);
}

function parseChecklist(lines: string[]): string[] {
  const items: string[] = [];
  for (const raw of lines) {
    const match = /\[[ xX]\]\s*(.+)$/.exec(raw);
    if (!match || !match[1]) continue;
    const item = stripMarkdown(match[1]);
    if (item && !items.includes(item)) items.push(item);
  }
  return items;
}

function parsePieces(lines: string[], headings: Heading[]): string[] {
  const pieces: string[] = [];
  const pieceHeadings = headings.filter((heading) =>
    /pieces principales|pieces a fournir|documents? requis|a preparer/.test(norm(heading.title)),
  );
  const looksLikeDocument =
    /statut|piece|attestation|certificat|copie|extrait|declaration|document|contrat|titre|acte|autorisation|cahier|\bcin\b|passeport|identite|justificatif|bilan|facture|\bpv\b|proces|fiche|dossier|plan|rapport|etats financiers/i;

  for (const heading of pieceHeadings) {
    for (const raw of sectionLines(lines, heading)) {
      const match = /^\s*[-*]\s+(.*)$/.exec(raw);
      if (!match || !match[1]) continue;
      if (/^\s*[-*]\s*\[[ xX]\]/.test(raw)) continue;
      const item = stripMarkdown(match[1]).replace(/\.$/, "");
      if (!item || !looksLikeDocument.test(item)) continue;
      if (!pieces.includes(item)) pieces.push(item);
    }
  }

  return pieces;
}

function parseDelais(lines: string[], headings: Heading[]): string[] {
  const collected: string[] = [];
  const delaiHeadings = headings.filter((heading) => {
    const normalized = norm(heading.title);
    return normalized.includes("delai") || normalized === "repere general";
  });

  for (const heading of delaiHeadings) {
    for (const raw of sectionLines(lines, heading)) {
      const line = stripMarkdown(raw);
      if (line) collected.push(line);
    }
  }

  return collected;
}

function parseSource(lines: string[], headings: Heading[]): string {
  const heading = headings.find((entry) => norm(entry.title) === "source");
  if (!heading) return "";
  return bodyToDescription(sectionLines(lines, heading), 600);
}

function parseTitle(lines: string[]): string {
  const heading = lines.find((line) => /^#\s+/.test(line));
  if (!heading) return "";
  return heading
    .replace(/^#\s+/, "")
    .replace(/^(DGI|APII|RNE)\s*[—\-–:]\s*/i, "")
    .replace(/^\d+\.\s*/, "")
    .trim();
}

function extractUrls(text: string): string[] {
  return [...text.matchAll(/https?:\/\/[^\s)>"']+/g)].map((match) =>
    match[0].replace(/[.,;]+$/, ""),
  );
}

function extractLawRefs(text: string): string[] {
  const patterns = [
    /Loi\s+n[°o]?\s*[\d-]+(?:\s+du\s+[^,;.)\n]+)?/gi,
    /Décret(?:-loi)?\s+n[°o]?\s*[\d-]+(?:\s+du\s+[^,;.)\n]+)?/gi,
    /Code\s+(?:de\s+commerce|de\s+l'IRPP[^,;.\n]*|du\s+travail|des\s+sociétés\s+commerciales)/gi,
    /RNE\s+[A-Z]\s*\d+(?:\.\d+)?/g,
  ];
  const refs: string[] = [];
  for (const pattern of patterns) {
    for (const match of text.matchAll(pattern)) {
      const ref = match[0].replace(/\s+/g, " ").trim();
      if (ref && !refs.includes(ref)) refs.push(ref);
    }
  }
  return refs;
}

function extractFees(
  delaisLines: string[],
  fullText: string,
): Array<{ amount: string; note: string }> {
  const found: Array<{ amount: string; note: string }> = [];
  const seen = new Set<string>();

  for (const line of delaisLines) {
    if (!line) continue;
    for (const match of line.matchAll(/(\d+(?:[.,]\d+)?)\s*(TND|DT)\b/gi)) {
      const amount = (match[1] ?? "").replace(",", ".");
      if (seen.has(amount)) continue;
      seen.add(amount);
      found.push({ amount, note: truncate(line, 180) });
    }
  }

  if (found.length === 0) {
    for (const line of fullText.split("\n")) {
      const stripped = stripMarkdown(line);
      if (!/redevance|frais|pay|DT\b|TND/i.test(stripped)) continue;
      for (const match of stripped.matchAll(/(\d+(?:[.,]\d+)?)\s*(TND|DT)\b/gi)) {
        const amount = (match[1] ?? "").replace(",", ".");
        if (seen.has(amount)) continue;
        seen.add(amount);
        found.push({ amount, note: truncate(stripped, 180) });
      }
    }
  }

  return found;
}

function extractEstimatedDays(delaisLines: string[], steps: ParsedStep[]): number | null {
  const hints = [
    ...delaisLines,
    ...steps
      .filter((step) => /delai|délai/i.test(step.titleFr))
      .flatMap((step) => [step.titleFr, step.description]),
  ].join(" ");

  const days = /(\d+)\s*jours?\b/i.exec(hints);
  if (days && days[1]) return Number.parseInt(days[1], 10);

  const hours = /(\d+)\s*heures?\b/i.exec(hints);
  if (hours && hours[1]) return Math.ceil(Number.parseInt(hours[1], 10) / 24);

  return null;
}

