type ParsedFile = {
  agencyId: string;
  code: string;
  key: string;
  slug: string;
  relPath: string;
  nameFr: string;
  objective: string;
  steps: ParsedStep[];
  checklist: string[];
  pieces: string[];
  delaisLines: string[];
  sourceText: string;
  rawText: string;
};

const CODE_OVERRIDES: Record<string, { code: string; key: string }> = {
  "RNE/13-changer-dirigeant-societe": {
    code: "changement_gerant",
    key: "procedure_changement_gerant",
  },
};

function parseFile(agencyId: string, filePath: string): ParsedFile {
  const rawText = readFileSync(filePath, "utf8");
  const lines = rawText.split(/\r?\n/);
  const headings = parseHeadings(lines);
  const base = path.basename(filePath, ".md");
  const slug = base.replace(/^\d+[-_]/, "");
  const override = CODE_OVERRIDES[`${agencyId}/${base}`];
  const code = override?.code ?? slugify(slug);
  const key = override?.key ?? `procedure_${agencyId.toLowerCase()}_${code}`;
  const title = parseTitle(lines);
  const pieces = parsePieces(lines, headings);
  const steps = parseSteps(lines, headings);
  const delaisLines = parseDelais(lines, headings);

  return {
    agencyId,
    code,
    key,
    slug,
    relPath: path.relative(REPO_ROOT, filePath),
    nameFr: title,
    objective: parseObjective(lines, headings),
    steps,
    checklist: parseChecklist(lines),
    pieces,
    delaisLines,
    sourceText: parseSource(lines, headings),
    rawText,
  };
}

// -----------------------------------------------------------------------------
// stepType / category / obligations classification
// -----------------------------------------------------------------------------

type StepType = "info" | "form" | "upload" | "payment" | "review" | "submission";

function inferStepType(titleFr: string, description: string): StepType {
  const text = norm(`${titleFr} ${description}`);

  if (/\b(payer|paiement|regler|redevance|droits?|montant du|frais de)\b/.test(text))
    return "payment";
  if (
    /\b(joindre|piece|pieces|justificatif|justificatifs|televers\w*|copie|documents?)\b|deposer les (documents|justificatifs|pieces)/.test(
      text,
    )
  ) {
    return "upload";
  }
  if (/\b(deposer|depot|soumettre|envoyer|envoi|transmettre|transmission|remettre)\b/.test(text)) {
    return "submission";
  }
  if (/\b(remplir|saisir|renseigner|formulaire|declaration|declarer|ecran|fiche)\b/.test(text)) {
    return "form";
  }
  if (
    /\b(verifier|suivre|attendre|consulter|controler|conserver|archiver|identifier|preparer|choisir|selectionner|accomplir|obtenir|recuperer|determiner)\b/.test(
      text,
    )
  ) {
    return "info";
  }
  return "info";
}

