// Document types
// -----------------------------------------------------------------------------

type DocEntry = {
  key: string;
  code: string;
  agencyId: string | null;
  nameFr: string;
  nameAr: string;
  description: string;
  acceptedMimeTypes: string[];
  requiredFields: string[];
  validityDays: number | null;
  source: "existing" | "generated";
  tokens: string[];
};

const DOC_STOPWORDS = new Set([
  "document",
  "documents",
  "dossier",
  "dossiers",
  "piece",
  "pieces",
  "information",
  "informations",
  "entreprise",
  "activity",
  "activite",
  "demande",
  "copie",
  "selon",
  "necessaire",
  "necessaires",
  "applicable",
  "applicables",
  "enregistres",
  "enregistre",
]);

function docTokens(nameFr: string): string[] {
  return norm(nameFr)
    .split(" ")
    .filter((token) => token.length >= 5 && !DOC_STOPWORDS.has(token));
}

const GENERIC_DOC_CODES = new Set([
  "cin",
  "passeport",
  "justificatif_adresse",
  "facture",
  "titre_de_propriete",
  "autorisation",
  "cahier_des_charges",
  "cin_carte_de_residence",
  "autorisation_ou_cahier_des_charges",
]);

