function docNameFromPiece(piece: string): string {
  let value = piece.split(",")[0]?.trim() ?? piece;
  value = value
    .replace(/\s+(selon|si|pour|lorsqu|en cas|dans le cas|le cas)\b.*$/i, "")
    .replace(/\s*\/\s*/g, " / ")
    .replace(/\.$/, "")
    .trim();
  if (value.length > 80) value = truncate(value, 80).replace(/…$/, "").trim();
  return value;
}

function buildDocumentRegistry(files: ParsedFile[]): {
  registry: DocEntry[];
  generated: DocEntry[];
} {
  const registry: DocEntry[] = [];
  const byName = new Set<string>();
  const byCode = new Set<string>();

  for (const doc of DOCUMENT_TYPES) {
    const entry: DocEntry = { ...doc, source: "existing", tokens: docTokens(doc.nameFr) };
    registry.push(entry);
    byName.add(norm(doc.nameFr));
    byCode.add(doc.code);
  }

  const generated: DocEntry[] = [];

  for (const curated of CURATED_DOCS) {
    if (byCode.has(curated.code) || byName.has(norm(curated.nameFr))) continue;
    const entry: DocEntry = { ...curated, source: "generated", tokens: docTokens(curated.nameFr) };
    registry.push(entry);
    generated.push(entry);
    byName.add(norm(curated.nameFr));
    byCode.add(curated.code);
  }

  for (const file of files) {
    for (const piece of file.pieces) {
      const nameFr = docNameFromPiece(piece);
      if (!nameFr) continue;
      const normalized = norm(nameFr);
      if (byName.has(normalized)) continue;
      const code = slugify(nameFr);
      if (!code || byCode.has(code)) continue;
      const agencyId = GENERIC_DOC_CODES.has(code) ? null : file.agencyId;
      const entry: DocEntry = {
        key: `doc_${code}`,
        code,
        agencyId,
        nameFr,
        nameAr: docArabic(nameFr) ?? nameFr,
        description: `Pièce requise pour les formalités ${file.agencyId}.`,
        acceptedMimeTypes: /cin|passeport|identite|justificatif|facture/i.test(code)
          ? [PDF, JPEG, PNG]
          : [PDF],
        requiredFields: [],
        validityDays: null,
        source: "generated",
        tokens: docTokens(nameFr),
      };
      registry.push(entry);
      generated.push(entry);
      byName.add(normalized);
      byCode.add(code);
    }
  }

  return { registry, generated };
}

const DOC_SYNONYMS: Array<[RegExp, string]> = [
  [/\bnomination\b/, "pv_nomination_gerant"],
  [/\bproces verbal\b|\bpv d assemblee\b/, "pv_assemblee_generale"],
  [/\bbeneficiaire effectif\b/, "declaration_beneficiaire"],
  [
    /\bcarte d identification fiscale\b|\bcarte fiscale\b|\bidentifiant fiscal\b/,
    "carte_identification_fiscale",
  ],
  [/\bdeclaration d existence\b/, "declaration_existence"],
  [/\battestation de depot\b|\badd\b/, "attestation_depot_declaration"],
  [/\bcahier des charges\b/, "cahier_des_charges"],
  [/\bactes constitutifs\b|\bstatuts enregistres\b/, "actes_constitutifs"],
  [/\bstatuts?\b/, "statuts"],
  [/\bcarte d identite\b|\bpiece d identite\b|\bcin\b|\bcarte nationale\b/, "cin"],
  [/\bpasseport\b/, "passeport"],
  [
    /\bjustificatif de domicile\b|\btitre de propriete\b|\bcontrat de location\b|\bbail\b/,
    "justificatif_adresse",
  ],
  [/\battestation bancaire\b|\bdepot de capital\b|\bcompte bloque\b/, "attestation_banque"],
  [/\betats financiers\b|\bbilan\b/, "etats_financiers"],
  [/\bextraits?\b/, "rne_extrait"],
  [/\bautorisation\b/, "autorisation"],
];

function matchDocumentType(
  text: string,
  registry: DocEntry[],
): { key: string | null; strong: boolean } {
  const normalized = ` ${norm(text)} `;

  for (const [pattern, code] of DOC_SYNONYMS) {
    if (pattern.test(normalized)) {
      const found = registry.find((entry) => entry.code === code);
      if (found) return { key: found.key, strong: true };
    }
  }

  let best: { key: string; score: number } | null = null;
  for (const entry of registry) {
    let score = 0;
    for (const token of entry.tokens) {
      if (normalized.includes(` ${token} `) || normalized.includes(` ${token}s `))
        score += token.length;
    }
    if (score > 0 && (!best || score > best.score)) best = { key: entry.key, score };
  }

  return { key: best?.key ?? null, strong: false };
}

